func (r Recipe) Dose() int {
	return Portions(r.Name) * r.Cups
}

func (r Recipe) Scale(cups, extra int, labels ...string) Recipe {
	r.Cups = cups + extra
	if len(labels) > 0 {
		r.Name = Normalize(labels[0])
	}
	return r
}

